import pandas as pd

NULL_SENTINEL = "<<NULL>>"


def _resolve_field(value, current, is_email=False):
    """Apply the change-field rule for a single field.

    value: the field value coming from the change row (may be NaN/None).
    current: current value held for this field (may be None).
    """
    if pd.isna(value):
        # NULL in change -> leave unchanged
        return current
    if value == NULL_SENTINEL:
        return None
    if is_email:
        return str(value).strip().lower()
    return value


def _nullsafe_eq(a, b):
    a_null = a is None or (isinstance(a, float) and pd.isna(a))
    b_null = b is None or (isinstance(b, float) and pd.isna(b))
    if a_null and b_null:
        return True
    if a_null != b_null:
        return False
    return a == b


def run(inputs: dict) -> dict:
    customer_profile = inputs["customer_profile"]
    profile_changes = inputs["profile_changes"]

    # Index existing profiles by customer_id
    existing_by_cust = {}
    for _, row in customer_profile.iterrows():
        existing_by_cust[row["customer_id"]] = {
            "email": row["email"] if not pd.isna(row["email"]) else None,
            "phone": row["phone"] if not pd.isna(row["phone"]) else None,
            "tier": row["tier"] if not pd.isna(row["tier"]) else None,
            "updated_seq": row["updated_seq"],
        }

    # Group changes by customer_id, sorted by change_seq
    changes_by_cust = {}
    for cust_id, grp in profile_changes.groupby("customer_id"):
        grp_sorted = grp.sort_values("change_seq", kind="mergesort")
        changes_by_cust[cust_id] = grp_sorted.to_dict("records")

    all_customer_ids = set(existing_by_cust.keys()) | set(changes_by_cust.keys())

    result_rows = []

    for cust_id in all_customer_ids:
        existing_row = existing_by_cust.get(cust_id)

        if existing_row is not None:
            current = {
                "email": existing_row["email"],
                "phone": existing_row["phone"],
                "tier": existing_row["tier"],
            }
            updated_seq = existing_row["updated_seq"]
            exists = True
        else:
            current = {"email": None, "phone": None, "tier": None}
            updated_seq = None
            exists = False

        cust_changes = changes_by_cust.get(cust_id, [])

        if exists:
            cust_changes = [c for c in cust_changes if c["change_seq"] > updated_seq]

        for c in cust_changes:
            new_email = _resolve_field(c["email"], current["email"], is_email=True)
            new_phone = _resolve_field(c["phone"], current["phone"], is_email=False)
            new_tier = _resolve_field(c["tier"], current["tier"], is_email=False)

            if not exists:
                # Creation: never a no-op
                current = {"email": new_email, "phone": new_phone, "tier": new_tier}
                updated_seq = c["change_seq"]
                exists = True
            else:
                same = (
                    _nullsafe_eq(new_email, current["email"])
                    and _nullsafe_eq(new_phone, current["phone"])
                    and _nullsafe_eq(new_tier, current["tier"])
                )
                if same:
                    # no-op, do not advance updated_seq
                    pass
                else:
                    current = {"email": new_email, "phone": new_phone, "tier": new_tier}
                    updated_seq = c["change_seq"]

        result_rows.append(
            {
                "customer_id": cust_id,
                "email": current["email"],
                "phone": current["phone"],
                "tier": current["tier"],
                "updated_seq": updated_seq,
            }
        )

    new_profile = pd.DataFrame(
        result_rows, columns=["customer_id", "email", "phone", "tier", "updated_seq"]
    )

    if not new_profile.empty:
        new_profile["customer_id"] = new_profile["customer_id"].astype("int64")
        new_profile["updated_seq"] = new_profile["updated_seq"].astype("int64")
    else:
        new_profile = pd.DataFrame(
            {
                "customer_id": pd.Series(dtype="int64"),
                "email": pd.Series(dtype="object"),
                "phone": pd.Series(dtype="object"),
                "tier": pd.Series(dtype="object"),
                "updated_seq": pd.Series(dtype="int64"),
            }
        )

    new_profile = new_profile.sort_values("customer_id", kind="mergesort").reset_index(
        drop=True
    )

    return {"new_profile": new_profile}
